{"file_text": ".message-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #fff;
    overflow: hidden;
}

.panel-header {
    padding: 12px 20px;
    border-bottom: 1px solid #e0e0e0;
    flex-shrink: 0;
}

.panel-header h2 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
    color: #1a1a1a;
}

.panel-description {
    font-size: 0.82rem;
    color: #777;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 12px 0;
}

.loading-indicator {
    text-align: center;
    padding: 12px;
    color: #999;
    font-size: 0.85rem;
}

.message-input-area {
    display: flex;
    gap: 8px;
    padding: 12px 16px;
    border-top: 1px solid #e0e0e0;
    background: #fafafa;
    flex-shrink: 0;
}

.message-textarea {
    flex: 1;
    padding: 8px 12px;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 0.9rem;
    font-family: inherit;
    resize: none;
    outline: none;
    transition: border-color 0.15s;
}

.message-textarea:focus {
    border-color: #1976d2;
}

.send-btn {
    padding: 8px 20px;
    background-color: #1976d2;
    color: #fff;
    border: none;
    border-radius: 6px;
    font-weight: 600;
    font-size: 0.9rem;
    cursor: pointer;
    align-self: flex-end;
    transition: background-color 0.15s;
}

.send-btn:hover:not(:disabled) {
    background-color: #1565c0;
}

.send-btn:disabled {
    background-color: #bbb;
    cursor: not-allowed;
}

