{"file_text": "@* Right panel — thread view with root message, replies, and reply input *@

<div class="thread-panel">
    <div class="thread-header">
        <h3>Thread</h3>
        <button class="close-btn" @onclick="OnClose" title="Close thread">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root">
            <MessageBubble Message="RootMessage"
                           ShowReplyAction="false"
                           OnReact="emoji => OnReact.InvokeAsync((RootMessage.Id, emoji))" />
        </div>

        <div class="reply-divider">
            <span>@Replies.Count @(Replies.Count == 1 ? "reply" : "replies")</span>
        </div>

        <div class="thread-replies">
            @foreach (var reply in Replies)
            {
                <MessageBubble Message="reply"
                               ShowReplyAction="false"
                               OnReact="emoji => OnReact.InvokeAsync((reply.Id, emoji))" />
            }
        </div>

        <div class="reply-input-area">
            <textarea class="reply-textarea"
                      rows="2"
                      placeholder="Reply…"
                      @bind="_replyText"
                      @onkeydown="HandleKeyDown" />
            <button class="reply-btn" @onclick="SendReply" disabled="@string.IsNullOrWhiteSpace(_replyText)">
                Reply
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public Message? RootMessage { get; set; }
    [Parameter] public List<Message> Replies { get; set; } = [];
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnSendReply { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private string _replyText = string.Empty;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendReply();
        }
    }

    private async Task SendReply()
    {
        if (string.IsNullOrWhiteSpace(_replyText)) return;
        var content = _replyText.Trim();
        _replyText = string.Empty;
        await OnSendReply.InvokeAsync(content);
    }
}
