@page "/chat"
@using sv_38a83a1f730041ce862144f488406b56.Components.Pages.Chat
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="sidebar-col">
        <ChannelSidebar Channels="_channels"
                        SelectedChannelId="@(_selectedChannel?.Id ?? 0)"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="main-col @(_isThreadOpen ? "" : "main-col-wide")">
