+        // Refresh the affected message in the main list
+        if (_selectedChannel is not null)
+        {
+            var refreshed = await ChatService.GetMessagesAsync(_selectedChannel.Id, 0, _skip);
+            _messages = refreshed;
+        }
+
+        // Refresh thread if open
+        if (_isThreadOpen && _threadRootMessage is not null)
+        {
+            var threadMessages = await ChatService.GetThreadAsync(_threadRootMessage.Id);
+            _threadRootMessage = threadMessages.FirstOrDefault(m => m.Id == _threadRootMessage.Id)
+                                  ?? _threadRootMessage;
+            _threadReplies = threadMessages.Where(m => m.Id != _threadRootMessage.Id).ToList();
+        }
