+@page "/chat"
+@using sv_38a83a1f730041ce862144f488406b56.Components.Pages.Chat
+@rendermode InteractiveServer
+@inject IChatService ChatService
+
+<PageTitle>Chat</PageTitle>
+
+<div class="chat-layout">
+    <div class="sidebar-col">
+        <ChannelSidebar Channels="_channels"
+                        SelectedChannelId="@(_selectedChannel?.Id ?? 0)"
+                        OnChannelSelected="SelectChannel" />
+    </div>
+
+    <div class="main-col @(_isThreadOpen ? "" : "main-col-wide")">
+        <MessagePanel Channel="_selectedChannel"
+                      Messages="_messages"
+                      ThreadReplyCounts="_threadReplyCounts"
+                      OnOpenThread="OpenThread"
+                      OnReact="HandleReaction"
+                      OnSendMessage="SendMessage"
+                      OnLoadMore="LoadOlderMessages" />
+    </div>
+
+    @if (_isThreadOpen)
+    {
+        <div class="thread-col">
+            <ThreadPanel RootMessage="_threadRootMessage"
+                         Replies="_threadReplies"
+                         OnClose="CloseThread"
+                         OnSendReply="SendThreadReply"
+                         OnReact="HandleReaction" />
+        </div>
+    }
+</div>
+
+@code {
+    private const int PageSize = 30;
+
+    private List<Channel> _channels = [];
+    private Channel? _selectedChannel;
+    private List<Message> _messages = [];
+    private Dictionary<int, int> _threadReplyCounts = new();
+    private int _skip;
+    private bool _hasMoreMessages = true;
+
+    // Thread state
+    private bool _isThreadOpen;
+    private Message? _threadRootMessage;
+    private List<Message> _threadReplies = [];
+
+    protected override async Task OnInitializedAsync()
+    {
+        _channels = await ChatService.GetChannelsAsync();
+        if (_channels.Count > 0)
+        {
+            await SelectChannel(_channels[0]);
+        }
+    }
+
+    private async Task SelectChannel(Channel channel)
+    {
+        _selectedChannel = channel;
+        _skip = 0;
+        _hasMoreMessages = true;
+        _messages = await ChatService.GetMessagesAsync(channel.Id, _skip, PageSize);
+        _skip = _messages.Count;
+        BuildThreadReplyCounts();
+
+        CloseThread();
+        await ChatService.MarkChannelReadAsync(channel.Id);
+
+        // Refresh channel list to update unread counts
+        _channels = await ChatService.GetChannelsAsync();
+    }
+
+    private async Task LoadOlderMessages()
+    {
+        if (_selectedChannel is null || !_hasMoreMessages) return;
+
+        var older = await ChatService.GetMessagesAsync(_selectedChannel.Id, _skip, PageSize);
+        if (older.Count < PageSize) _hasMoreMessages = false;
+
+        _messages.InsertRange(0, older);
+        _skip += older.Count;
+        BuildThreadReplyCounts();
+    }
+
+    private async Task SendMessage(string content)
+    {
+        if (_selectedChannel is null) return;
+
+        var msg = await ChatService.SendMessageAsync(_selectedChannel.Id, content, null);
+        _messages.Add(msg);
+        _skip++;
+    }
+
+    private async Task OpenThread(int rootMessageId)
+    {
+        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == rootMessageId);
+        if (_threadRootMessage is null) return;
+
+        var threadMessages = await ChatService.GetThreadAsync(rootMessageId);
+        // First message is the root; rest are replies
+        _threadReplies = threadMessages.Where(m => m.Id != rootMessageId).ToList();
+        _isThreadOpen = true;
+    }
+
+    private void CloseThread()
+    {
+        _isThreadOpen = false;
+        _threadRootMessage = null;
+        _threadReplies = [];
+    }
+
+    private async Task SendThreadReply(string content)
+    {
+        if (_selectedChannel is null || _threadRootMessage is null) return;
+
+        var reply = await ChatService.SendMessageAsync(
+            _selectedChannel.Id, content, _threadRootMessage.Id);
+        _threadReplies.Add(reply);
+
+        // Update reply count in main view
+        _threadReplyCounts[_threadRootMessage.Id] =
+            _threadReplyCounts.GetValueOrDefault(_threadRootMessage.Id) + 1;
+    }
+
+    private async Task HandleReaction((int MessageId, string Emoji) args)
+    {
+        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
+
+        // Refresh the affected message in the main list
+        if (_selectedChannel is not null)
+        {
+            var refreshed = await ChatService.GetMessagesAsync(_selectedChannel.Id, 0, _skip);
+            _messages = refreshed;
+        }
+
+        // Refresh thread if open
+        if (_isThreadOpen && _threadRootMessage is not null)
+        {
+            var threadMessages = await ChatService.GetThreadAsync(_threadRootMessage.Id);
+            _threadRootMessage = threadMessages.FirstOrDefault(m => m.Id == _threadRootMessage.Id)
+                                  ?? _threadRootMessage;
+            _threadReplies = threadMessages.Where(m => m.Id != _threadRootMessage.Id).ToList();
+        }
+    }
+
+    private void BuildThreadReplyCounts()
+    {
+        // Count messages that are replies (have a ReplyToId) grouped by root
+        _threadReplyCounts = _messages
+            .Where(m => m.ReplyToId.HasValue)
+            .GroupBy(m => m.ReplyToId!.Value)
+            .ToDictionary(g => g.Key, g => g.Count());
+    }
+}
+

